BEGIN;
UPDATE public.config SET value='true' WHERE key='multi_tenant_enabled';
INSERT INTO auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data)
VALUES ('ce8f8da2-0e18-4200-bb52-977aac215332','mcp-rollback-test@example.invalid',now(),'{}','{}');
SELECT set_config('request.jwt.claims','{"sub":"ce8f8da2-0e18-4200-bb52-977aac215332","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT public.tenant_onboard('MCP operações teste rollback');
RESET ROLE;
INSERT INTO auth.sessions(id,user_id) VALUES('a202a202-1111-4111-8111-222222222222','ce8f8da2-0e18-4200-bb52-977aac215332');
INSERT INTO crm_mcp.clients(client_id,resource,can_write,is_active) VALUES('test-crm-operations','https://test.example/mcp',true,true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub','ce8f8da2-0e18-4200-bb52-977aac215332','role','authenticated','client_id','test-crm-operations','aud','https://test.example/mcp','session_id','a202a202-1111-4111-8111-222222222222','app_metadata',(SELECT raw_app_meta_data FROM auth.users WHERE id='ce8f8da2-0e18-4200-bb52-977aac215332'))::text,true);
RESET ROLE;
DO $$ DECLARE tid uuid:=public.get_tenant_id();a uuid;l uuid;d uuid;sid uuid;mid uuid;pid uuid;st uuid;r jsonb;hid uuid;BEGIN
 SELECT id INTO mid FROM public.team_members WHERE auth_user_id=auth.uid() AND tenant_id=tid;
 SELECT id INTO pid FROM public.sales_pipelines WHERE tenant_id=tid LIMIT 1;
 SELECT id INTO st FROM public.sales_pipeline_stages WHERE pipeline_id=pid AND NOT is_lost AND NOT is_won ORDER BY position LIMIT 1;
 INSERT INTO public.agents_registry(tenant_id,slug,display_name,provider,model,system_prompt,is_active) VALUES(tid,'loss-test-'||gen_random_uuid(),'Teste','openai','test','Prompt de teste',false) RETURNING id INTO a;
 INSERT INTO public.leads(tenant_id,name) VALUES(tid,'Contato QA') RETURNING id INTO l;
 INSERT INTO public.deals(tenant_id,lead_id,title,pipeline_id,pipeline_stage_id,status) VALUES(tid,l,'Teste perda',pid,st,'open') RETURNING id INTO d;
 INSERT INTO public.agents_sessions(tenant_id,agent_id,user_id,channel,playground_context) VALUES(tid,a,mid,'playground',jsonb_build_object('lead_id',l,'deal_id',d)) RETURNING id INTO sid;
 r:=public.mcp_configure_operational_skill(gen_random_uuid(),a,'mark_deal_lost',true);
 IF NOT EXISTS(SELECT 1 FROM public.agents_tools WHERE agent_id=a AND name='mark_deal_lost' AND is_active AND NOT requires_approval) THEN RAISE EXCEPTION 'Habilidade não ativada';END IF;
 BEGIN PERFORM public.playground_mark_deal_lost(d,a,'',sid);RAISE EXCEPTION 'Motivo vazio aceito';EXCEPTION WHEN SQLSTATE '22023' THEN NULL;END;
 BEGIN PERFORM public.playground_mark_deal_lost(d,a,'Desistência',gen_random_uuid());RAISE EXCEPTION 'Sessão externa aceita';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.playground_mark_deal_lost(d,a,'Desistência explícita do contato',sid);
 IF r->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM public.deals d JOIN public.sales_pipeline_stages st ON st.id=d.pipeline_stage_id WHERE d.id=(r->>'deal_id')::uuid AND d.status='lost' AND st.is_lost AND d.lost_reason='Desistência explícita do contato') THEN RAISE EXCEPTION 'Perda não persistiu';END IF;
 r:=public.playground_mark_deal_lost(d,a,'Desistência explícita do contato',sid);
 IF r->>'already_lost'<>'true' OR (SELECT count(*) FROM public.lead_interactions WHERE lead_id=l AND metadata->>'action'='mark_deal_lost')<>1 THEN RAISE EXCEPTION 'Repetição duplicou perda';END IF;
 r:=public.playground_notify_human(a,mid,sid,'Preciso de um humano para revisar a reunião');hid:=(r->>'handoff_id')::uuid;
 IF r->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM public.company_activities WHERE id=(r->>'task_id')::uuid AND tenant_id=tid AND lead_id=l) THEN RAISE EXCEPTION 'Tarefa não criada';END IF;
 r:=public.playground_notify_human(a,mid,sid,'Preciso de um humano para revisar a reunião');
 IF (r->>'handoff_id')::uuid<>hid THEN RAISE EXCEPTION 'Encaminhamento duplicado';END IF;
 UPDATE public.deals SET status='won' WHERE id=d;
 BEGIN PERFORM public.playground_mark_deal_lost(d,a,'Não pode desfazer ganho',sid);RAISE EXCEPTION 'Negócio ganho alterado';EXCEPTION WHEN SQLSTATE '22023' THEN NULL;END;
 UPDATE crm_mcp.clients SET can_write=false WHERE client_id='test-crm-operations';
 BEGIN PERFORM public.mcp_configure_operational_skill(gen_random_uuid(),a,'mark_deal_lost',true);RAISE EXCEPTION 'Leitor configurou';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.playground_mark_deal_lost(d,a,'Leitor',sid);RAISE EXCEPTION 'Leitor escreveu';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_function_privilege('authenticated','public.agent_mark_deal_lost(uuid,uuid,text,uuid)','EXECUTE') THEN RAISE EXCEPTION 'RPC de serviço exposta';END IF;
END $$;
ROLLBACK;
